import{c as e,S as a,j as r,m as l}from"./chunks/framework.8aa1YH_s.js";const u=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 11: Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs)","description":"","frontmatter":{},"headers":[],"relativePath":"11 Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs).md","filePath":"11 Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs).md"}'),n={name:"11 Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs).md"};function s(m,i,o,t,k,d){return a(),r("div",null,[...i[0]||(i[0]=[l('<h1 id="turk-dil-bilgisi-serisi-11-sekil-bilgisi-fiil-cekim-ekleri-kip-zaman-ve-sahıs" tabindex="-1">Türk Dil Bilgisi Serisi - 11: Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs) <a class="header-anchor" href="#turk-dil-bilgisi-serisi-11-sekil-bilgisi-fiil-cekim-ekleri-kip-zaman-ve-sahıs" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 11: Şekil Bilgisi - Fiil Çekim Ekleri (Kip, Zaman ve Şahıs)”">​</a></h1><p>Şekil bilgisi serimizde isimlerin çekimini tamamladıktan sonra, şimdi dilimizin en dinamik, en hareketli mekanizmasına geçiyoruz: <strong>Fiil Çekim Ekleri</strong>.</p><p>Prof. Dr. Muharrem Ergin’e göre fiil çekimi, Türkçenin adeta yönetim merkezidir. Bir fiil kök veya gövdesi, bu ekler sayesinde zamana, mekâna, niyete ve eylemi yapan şahsa bağlanarak canlanır.</p><p>Türkçede bir fiilin çekimlenebilmesi için şu evrensel formül takip edilir: $$\\text{Fiil Kök/Gövdesi} + \\text{Kip Eki (Zaman/Tasarlama)} + \\text{Şahıs Eki}$$</p><hr><h2 id="_1-fiil-kipleri-zaman-ve-tasarlama-modları" tabindex="-1">1. Fiil Kipleri (Zaman ve Tasarlama Modları) <a class="header-anchor" href="#_1-fiil-kipleri-zaman-ve-tasarlama-modları" aria-label="Permalink to “1. Fiil Kipleri (Zaman ve Tasarlama Modları)”">​</a></h2><p>Muharrem Ergin sistematiğinde fiil kipleri iki ana gruba ayrılır: <strong>Bildirme (Zaman) Kipleri</strong> ve <strong>Tasarlama (Dilek) Kipleri</strong>.</p><h3 id="a-bildirme-zaman-haber-kipleri" tabindex="-1">A) Bildirme (Zaman / Haber) Kipleri <a class="header-anchor" href="#a-bildirme-zaman-haber-kipleri" aria-label="Permalink to “A) Bildirme (Zaman / Haber) Kipleri”">​</a></h3><p>Eylemin ne zaman yapıldığını doğrudan, kesin bir zaman vurgusuyla bildiren kiplerdir.</p><ol><li><strong>Görülen (Bilinen) Geçmiş Zaman (<code>-dı / -di / -du / -dü / -tı / -ti / -tu / -tü</code>):</strong> Konuşanın bizzat şahit olduğu, emin olduğu, geçmişte tamamlanmış eylemleri bildirir. <ul><li><em>Örnek:</em> Gel-<strong>di</strong>-m, yaz-<strong>dı</strong>-n.</li></ul></li><li><strong>Öğrenilen (Duyulan) Geçmiş Zaman (<code>-mış / -miş / -muş / -müş</code>):</strong> Eylemin geçmişte yapıldığını başkasından duyma, sonradan fark etme veya sonradan anlama yoluyla bildirir. <ul><li><em>Örnek:</em> Gel-<strong>miş</strong>-sin, uyu-<strong>muş</strong>-um.</li></ul></li><li><strong>Şimdiki Zaman (<code>-yor</code> / <code>-makta / -mekte</code>):</strong> Eylemin şu anda, konuşma anıyla aynı zamanda yapıldığını bildirir. <ul><li><em>Örnek:</em> Gidi-<strong>yor</strong>-um, yaz-<strong>makta</strong>-yız.</li></ul></li><li><strong>Gelecek Zaman (<code>-acak / -ecek</code>):</strong> Eylemin konuşma anından daha sonraki bir zaman diliminde yapılacağını bildirir. <ul><li><em>Örnek:</em> Gel-<strong>ecek</strong>-ler, yap-<strong>acağ</strong>-ım.</li></ul></li><li><strong>Geniş Zaman (<code>-r / -ar / -er / -ır / -ir / -ur / -ür</code>):</strong> Eylemin geçmiş, şimdi ve gelecek zamanların tümünü kapsayacak şekilde her zaman yapıldığını veya yapılacağını bildirir. <ul><li><em>Örnek:</em> Sever-<strong>i</strong>-m, yapar-<strong>sın</strong> (Olumsuzu: <em>-maz/-mez</em>: gel-<strong>mez</strong>-sin).</li></ul></li></ol><h3 id="b-tasarlama-dilek-kipleri" tabindex="-1">B) Tasarlama (Dilek) Kipleri <a class="header-anchor" href="#b-tasarlama-dilek-kipleri" aria-label="Permalink to “B) Tasarlama (Dilek) Kipleri”">​</a></h3><p>Bünyelerinde doğrudan bir zaman anlamı barındırmayan; eylemi istek, şart, emir veya gereklilik gibi bir niyet/tasarı moduna sokan kiplerdir.</p><ol><li><strong>Gereklilik Kipi (<code>-malı / -meli</code>):</strong> Eylemin yapılmasının zorunlu veya gerekli olduğunu bildirir. <ul><li><em>Örnek:</em> Çalış-<strong>malı</strong>-yım, git-<strong>meli</strong>-sin.</li></ul></li><li><strong>Şart (Koşul) Kipi (<code>-sa / -se</code>):</strong> Eylemin yapılmasını bir şarta bağlar veya dilek anlamı katar. <ul><li><em>Örnek:</em> Gel-<strong>se</strong>-n, oku-<strong>sa</strong>-k.</li></ul></li><li><strong>İstek Kipi (<code>-a / -e</code>):</strong> Eylemin yapılma isteğini, arzusunu bildirir. (Günümüz Türkçesinde daha çok 1. şahıslarda aktiftir). <ul><li><em>Örnek:</em> Gel-<strong>e</strong>-yim, gid-<strong>e</strong>-lim.</li></ul></li><li><strong>Emir Kipi (Eki yoktur):</strong> Eylemin yapılmasını emir şeklinde bildirir. 1. tekil ve 1. çoğul şahsın emri olmaz. Diğer şahıslar eklerle (şahıs ekleriyle birleşik olarak) çekimlenir. <ul><li><em>Örnek:</em> Gel (sen), gel-<strong>sin</strong> (o), gel-<strong>iniz</strong> (siz), gelsin-<strong>ler</strong> (onlar).</li></ul></li></ol><hr><h2 id="_2-sahıs-kisi-ekleri" tabindex="-1">2. Şahıs (Kişi) Ekleri <a class="header-anchor" href="#_2-sahıs-kisi-ekleri" aria-label="Permalink to “2. Şahıs (Kişi) Ekleri”">​</a></h2><p>Kip ekinden sonra gelerek, o eylemin <strong>kim tarafından yapıldığını</strong> gösteren eklerdir. Muharrem Ergin, Türkçedeki şahıs eklerini kökenlerine ve geldikleri kiplere göre gruplara ayırır, ancak en yaygın kullanılan klasik şahıs eki kadrosu şu şekildedir:</p><ul><li><strong>1. Tekil Şahıs (Ben):</strong> <code>-m, -ım, -im, -um, -üm</code> VEYA <code>-yım, -yim</code> $$\\rightarrow$$ Geldi-<strong>m</strong>, gidiyor-<strong>um</strong>.</li><li><strong>2. Tekil Şahıs (Sen):</strong> <code>-n, -sın, -sin, -sun, -sün</code> $$\\rightarrow$$ Geldi-<strong>n</strong>, gidiyor-<strong>sun</strong>.</li><li><strong>3. Tekil Şahıs (O):</strong> <em>Eki yoktur.</em> $$\\rightarrow$$ Geldi, gidiyor.</li><li><strong>1. Çoğul Şahıs (Biz):</strong> <code>-k, -ız, -iz, -uz, -üz</code> $$\\rightarrow$$ Geldi-<strong>k</strong>, gidiyor-<strong>uz</strong>.</li><li><strong>2. Çoğul Şahıs (Sizin):</strong> <code>-nız, -niz, -nuz, -nüz</code> VEYA <code>-sınız, -siniz</code> $$\\rightarrow$$ Geldi-<strong>niz</strong>, gidiyor-<strong>sunuz</strong>.</li><li><strong>3. Çoğul Şahıs (Onlar):</strong> <code>-lar / -ler</code> $$\\rightarrow$$ Geldi-<strong>ler</strong>, gidiyor-<strong>lar</strong>.</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in bu muazzam şeması bize gösteriyor ki, Türkçede fiil çekimi tamamen simetrik ve kusursuz bir hiyerarşiye sahiptir. Kökün üzerine önce zamanı veya modu koyar, en sona da o işi yapanın imzasını (şahsı) atarız. Bu matematiksel dizilim sayesinde Türkçede tek bir kelimeyle koca bir cümleyi (Örn: <em>Gidemediklerinizdendim</em>) ifade etmek mümkün olmaktadır.</p><p>Şekil bilgisinin en hareketli motorunu da başarıyla tamamladık aslanım!</p><p>Serimizin 12. bölümünde, kelimelerin cümle içindeki rollerine göre büründükleri kimlikleri inceleyeceğimiz <strong>&quot;Kelime Türleri&quot;</strong> dünyasına giriş yapıyoruz. İlk durağımız: <strong>İsimler ve İsim Tamlamaları</strong>.</p><p>Sayfayı çeviriyoruz, komutunu beklemedeyim!</p>',23)])])}const y=e(n,[["render",s]]);export{u as __pageData,y as default};
